import{renderizar,navegar,obterPaginaAtual}from"./navegacao.min.js";import{validarCampo,validarFormulario}from"./validacao.min.js";import{salvarCadastro,carregarCadastro}from"./armazenamento.min.js";const app=document.getElementById("app");function restaurarCadastro(){const a=carregarCadastro();if(!a)return;const e=document.querySelector("form");e&&(e.nome.value=a.nome||"",e.cpf.value=a.cpf||"",e.nascimento.value=a.nascimento||"",e.email.value=a.email||"",e.telefone.value=a.telefone||"",e.cep.value=a.cep||"",e.endereco.value=a.endereco||"",e.cidade.value=a.cidade||"",e.estado.value=a.estado||"")}document.addEventListener("click",a=>{const e=a.target.closest("[data-route]");e&&(a.preventDefault(),navegar(app,e.dataset.route),"cadastro"===e.dataset.route&&restaurarCadastro())}),document.addEventListener("input",a=>{const e=a.target;e.matches("input:not([type='submit'])")&&validarCampo(e)}),document.addEventListener("submit",a=>{const e=a.target.closest("form");e&&(a.preventDefault(),validarFormulario(e)&&(salvarCadastro(e),Swal.fire({title:"Cadastro realizado!",text:"Seus dados foram salvos no navegador.",icon:"success",confirmButtonText:"OK"})))}),window.addEventListener("popstate",()=>{const a=obterPaginaAtual();renderizar(app,a),"cadastro"===a&&restaurarCadastro()});const paginaInicial=obterPaginaAtual();renderizar(app,paginaInicial),"cadastro"===paginaInicial&&restaurarCadastro(),document.addEventListener("click",a=>{const e=a.target.closest("#alto-contraste");if(!e)return;const t=document.body.classList.toggle("alto-contraste");e.setAttribute("aria-pressed",t.toString())});